CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,display_name TEXT NOT NULL,primary_device_id TEXT,device_epoch INTEGER NOT NULL DEFAULT 0 CHECK(device_epoch>=0));
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at INTEGER NOT NULL,revoked_at INTEGER);
CREATE INDEX sessions_user ON sessions(user_id,expires_at);
CREATE TABLE groups(id TEXT PRIMARY KEY,name TEXT NOT NULL,time_zone TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id));
CREATE TABLE memberships(group_id TEXT REFERENCES groups(id),user_id TEXT REFERENCES users(id),role TEXT NOT NULL CHECK(role IN ('owner','member')),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),PRIMARY KEY(group_id,user_id));
CREATE INDEX membership_user ON memberships(user_id,active);
CREATE TABLE invitations(token_hash TEXT PRIMARY KEY,group_id TEXT NOT NULL REFERENCES groups(id),expires_at INTEGER NOT NULL,remaining_uses INTEGER NOT NULL CHECK(remaining_uses>=0));
CREATE TABLE tasks(id TEXT PRIMARY KEY,group_id TEXT NOT NULL REFERENCES groups(id),title TEXT NOT NULL,assignee_uid TEXT REFERENCES users(id),created_by_uid TEXT NOT NULL REFERENCES users(id),activate_at INTEGER,due_at INTEGER,status TEXT NOT NULL CHECK(status IN ('pending','completed','cancelled')),version INTEGER NOT NULL CHECK(version>0),completed_by_uid TEXT REFERENCES users(id),completed_at INTEGER,CHECK(activate_at IS NULL OR due_at IS NULL OR due_at>=activate_at));
CREATE TABLE alarm_requests(id TEXT PRIMARY KEY,group_id TEXT NOT NULL REFERENCES groups(id),creator_uid TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,note TEXT,task_id TEXT REFERENCES tasks(id),request_version INTEGER NOT NULL CHECK(request_version>0),status TEXT NOT NULL CHECK(status IN ('ACTIVE','WITHDRAWN','EXPIRED')),mode TEXT NOT NULL CHECK(mode IN ('ALARM','NOTIFICATION')),time_spec TEXT NOT NULL,recurrence TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,withdrawn_at INTEGER);
CREATE INDEX alarm_creator ON alarm_requests(creator_uid,updated_at);
CREATE TABLE alarm_recipients(request_id TEXT REFERENCES alarm_requests(id),recipient_uid TEXT REFERENCES users(id),received_version INTEGER NOT NULL CHECK(received_version>0),reception TEXT NOT NULL CHECK(reception IN ('RECEIVED','NOT_ACKNOWLEDGED')),decision TEXT NOT NULL CHECK(decision IN ('PENDING','ACCEPTED','REJECTED','DISABLED','NEEDS_REVIEW')),decision_revision INTEGER NOT NULL CHECK(decision_revision>0),accepted_request_version INTEGER,chosen_time_spec TEXT,consent_scope TEXT CHECK(consent_scope IN ('THIS_OCCURRENCE','SERIES')),reason TEXT,updated_at INTEGER NOT NULL,PRIMARY KEY(request_id,recipient_uid));
CREATE INDEX alarm_inbox ON alarm_recipients(recipient_uid,request_id);
CREATE TABLE devices(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),platform TEXT NOT NULL CHECK(platform IN ('android','ios','web')),push_token TEXT,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)));
CREATE TABLE device_schedules(request_id TEXT NOT NULL,recipient_uid TEXT NOT NULL,occurrence_id TEXT NOT NULL,device_id TEXT NOT NULL REFERENCES devices(id),device_epoch INTEGER NOT NULL CHECK(device_epoch>0),request_version INTEGER NOT NULL,decision_revision INTEGER NOT NULL,mode TEXT NOT NULL,mechanism TEXT NOT NULL,status TEXT NOT NULL,effective_at INTEGER NOT NULL,reported_at INTEGER NOT NULL,reason TEXT,updated_at INTEGER NOT NULL,PRIMARY KEY(request_id,recipient_uid,occurrence_id,device_id,device_epoch),FOREIGN KEY(request_id,recipient_uid) REFERENCES alarm_recipients(request_id,recipient_uid));
CREATE TABLE operations(actor_uid TEXT REFERENCES users(id),operation_id TEXT,kind TEXT NOT NULL,payload_hash TEXT NOT NULL,receipt TEXT NOT NULL,PRIMARY KEY(actor_uid,operation_id));
CREATE TABLE change_events(seq INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL REFERENCES users(id),group_id TEXT NOT NULL REFERENCES groups(id),request_id TEXT,kind TEXT NOT NULL CHECK(kind IN ('upsert','revoke')),created_at INTEGER NOT NULL);
CREATE INDEX feed_user ON change_events(user_id,seq);
CREATE TABLE sync_cursors(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),seq INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE outbox_events(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),request_id TEXT NOT NULL REFERENCES alarm_requests(id),request_version INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,available_at INTEGER NOT NULL,lease_until INTEGER,delivered_at INTEGER,last_error TEXT);
CREATE INDEX outbox_pending ON outbox_events(delivered_at,available_at,lease_until);
CREATE TABLE push_receipts(ticket_id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES outbox_events(id),device_id TEXT NOT NULL REFERENCES devices(id),checked_at INTEGER);
